0,"Create a Python program that implements a class for parsing and generating SQL queries. The class should have methods for constructing SQL SELECT statements with optional WHERE clauses, sorting, and limiting results. Additionally, the program should include functions for registering custom query generators, retrieving the generator associated with a given function name, and executing the generated SQL query using an external database connection.",94,,"['```
import sqlite3

class SqlQuery:
    def __init__(self):
        self.query = """"
        self.where_clause = """"
        self.order_by = """"
        self.limit = None
        self.offset = None

    def select(self, *fields):
        self.query = ""SELECT {}"".format("", "".join(fields))
        return self

    def from_(self, table):
        self.query += "" FROM {}"".format(table)
        return self

    def where(self, condition):
        if self.where_clause:
            self.where_clause += "" AND {}"".format(condition)
        else:
            self.where_clause = ""WHERE {}"".format(condition)
        return self

    def order_by(self, *fields):
        self.order_by = "", "".join(fields)
        return self

    def limit(self, n):
        self.limit = n
        return self

    def offset(self, n):
        self.offset = n
        return self

    def execute(self, connection):
        cursor = connection.cursor()
        if self.where_clause:
            self.query += "" {}"".format(self.where_clause)
        if self.order_by:
            self.query += "" ORDER BY {}"".format(self.order_by)
        if self.limit:
            self.query += "" LIMIT {}"".format(self.limit)
        if self.offset:
            self.query += "" OFFSET {}"".format(self.offset)
        return cursor.execute(self.query)

    @staticmethod
    def register_generator(name, generator):
        globals()[name] = generator

    @staticmethod
    def get_generator(name):
        return globals().get(name)

# Example usage:
q = SqlQuery()
q.select(""*"").from_(""table_name"") \
  .where(""column1 > 5 AND column2 < 10"") \
  .order_by(""column3 DESC"") \
  .limit(10) \
  .offset(5)
print(q.query)
# Output: SELECT * FROM table_name WHERE column1 > 5 AND column2 < 10 ORDER BY column3 DESC LIMIT 10 OFFSET 5

# Registering a custom query generator
def generate_custom_query():
    return ""SELECT * FROM table_name WHERE column1 = 5""
SqlQuery.register_generator(""generate_custom_query"", generate_custom_query)

# Retrieving the generator associated with a given function name
print(SqlQuery.get_generator(""generate_custom_query"")())
# Output: SELECT * FROM table_name WHERE column1 = 5
