import os
import paho.mqtt.client as mqtt

def connect_to_mqtt_broker():
    # Load configuration from environment variables
    broker_url = os.getenv('MQTT_BROKER_URL', 'localhost')
    broker_port = int(os.getenv('MQTT_BROKER_PORT', 1883))
    username = os.getenv('MQTT_USERNAME', None)
    password = os.getenv('MQTT_PASSWORD', None)

    # Initialize MQTT client
    client = mqtt.Client()

    # Set callback functions
    def on_connect(client, userdata, flags, rc):
        if rc == 0:
            print(""Connected successfully"")
        else:
            print(f""Connection failed with code {rc}"")

    def on_disconnect(client, userdata, rc):
        if rc != 0:
            print(""Unexpected disconnection"")

    def on_message(client, userdata, message):
        topic = message.topic
        payload = message.payload.decode()
        print(f""Received message on {topic}: {payload}"")

    # Connect to MQTT broker
    try:
        client.username_pw_set(username=username, password=password)
        client.connect(broker_url, broker_port)
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect

        # Subscribe to multiple topics with different QoS levels
        subscriptions = {
            ""topic1"": (1,),  # QoS level 1
            ""topic2"": (2,),  # QoS level 2
            ""topic3"": (0,)   # QoS level 0 (default)
        }

        for topic in subscriptions.keys():
            try:
                client.subscribe(topic=topic,
                                 qos=subscriptions[topic][0])
                print(""Subscribed to {topic} with QoS {qos}"".format(topic=topic, qos=subscriptions[topic][0]))
            except Exception as e:
                print(""Failed to subscribe to {topic}: {error}"".format(topic=topic, error=e))
    except Exception as e:
        print(""Failed to connect to MQTT broker: {error}"".format(error=e))

if __name__ == ""__main__"":
    connect_to_mqtt_broker()
[/PYTHON]
