0,"Design a Python script that leverages the Flask web framework to create a RESTful API. The API should support two endpoints: one for uploading image files and another for processing these images. Upon receiving an image, the script should apply a specified filter (e.g., grayscale, blur) based on the request parameters and return the modified image as a response. Ensure the code includes necessary error handling for file uploads and processing failures.",807,,"[""```
from flask import Flask, request, send_file
import cv2

app = Flask(__name__)

@app.route('/upload', methods=['POST'])
def upload():
    # Get the uploaded image file from the POST request
    file = request.files['image']

    # Apply filter based on request parameters
    if 'grayscale' in request.form:
        img = cv2.imread(file)
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        return send_file(gray, as_attachment=True, attachment_filename='grayscale_image')
    elif 'blur' in request.form:
        img = cv2.imread(file)
        blurred = cv2.GaussianBlur(img, (5, 5), 0)
        return send_file(blurred, as_attachment=True, attachment_filename='blurred_image')
    else:
        # Handle invalid request parameters
        return 'Invalid filter', 400

if __name__ == '__main__':
    app.run()
