import math

class RandomPoint3D:
  def __init__(self, x_min, x_max, y_min, y_max, z_min, z_max):
    self.x_min = x_min
    self.x_max = x_max
    self.y_min = y_min
    self.y_max = y_max
    self.z_min = z_min
    self.z_max = z_max

  def get_random_point(self):
    x = random.uniform(self.x_min, self.x_max)
    y = random.uniform(self.y_min, self.y_max)
    z = random.uniform(self.z_min, self.z_max)
    return (x, y, z)

  def get_euclidean_distance(self, point1, point2):
    x1, y1, z1 = point1
    x2, y2, z2 = point2
    return math.sqrt((x2-x1)**2 + (y2-y1)**2 + (z2-z1)**2)

  def __str__(self):
    return f""RandomPoint3D(x_min={self.x_min}, x_max={self.x_max}, y_min={self.y_min}, y_max={self.y_max}, z_min={self.z_min}, z_max={self.z_max})""
