from flask import Flask, jsonify, request
import json

app = Flask(__name__)

# Load JSON file containing product information
with open('products.json') as f:
    products = json.load(f)

# Define function to sort products by price in ascending order
def sort_by_price(product):
    return product['price']

# Define function to filter products by category
def filter_by_category(products, category):
    return [product for product in products if product['category'] == category]

# Route for getting all products
@app.route('/')
def get_all_products():
    return jsonify(products)

# Route for sorting products by price in ascending order
@app.route('/sort-by-price/<direction>')
def sort_by_price(direction):
    if direction == 'asc':
        sorted_products = sorted(products, key=sort_by_price)
    else:
        sorted_products = sorted(products, key=sort_by_price, reverse=True)
    return jsonify(sorted_products)

# Route for filtering products by category
@app.route('/filter-by-category/<category>')
def filter_by_category(category):
    filtered_products = filter_by_category(products, category)
    return jsonify(filtered_products)
