    else:
        verbose = False

    # Check for config file option
    if 'config_file' in options:
        config_file = options['config_file']
    else:
        print(""Error: No configuration file specified"")
        return

    # Read configuration file line by line and log each line with timestamp
    with open(config_file, 'r') as f:
        for line in f:
            if verbose:
                print(f""{datetime.now()}: {line}"")
            else:
                print(line)

if __name__ == ""__main__"":
    process_args(sys.argv[1:])
