def validate_product(product):
    # Validate product information against quality standards (price range, availability, expiration dates)
    if not (product['price'] >= 10 and product['price'] <= 100):
        raise ValueError(f""Price for product {product['id']} is out of range."")
    if not product['availability']:
        raise ValueError(f""Product {product['id']} is currently unavailable."")
    if product['expiration_date'] < datetime.now().date():
        raise ValueError(f""Product {product['id']} has expired."")
    return True

# Define real-time sales analytics functionality
def perform_sales_analytics(data):
    # Perform immediate analytics on sales data (top-selling products, sales trends over time)
    top_sellers = {}
    sales_trend = []
    for sale in data:
        product_id = sale['product_id']
        if product_id not in top_sellers:
            top_sellers[product_id] = 1
        else:
            top_sellers[product_id] += 1
        sales_trend.append(datetime.now().date())
    return {'top_sellers': top_sellers, 'sales_trend': sales_trend}

# Define performance metrics tracking and alerts
def track_performance_metrics(data):
    # Track system performance metrics (update latency, throughput, memory usage) during high-volume transactions
