```python
# Import necessary libraries
import json
from flask import Flask, request, render_template
app = Flask(__name__)

# Define a function to parse JSON data and create HTML tables
def generate_tables(data):
    # Sort the data by price in descending order
    sorted_data = sorted(data['products'], key=lambda x: x['price'], reverse=True)

    # Create an HTML table for each category
    category_tables = {}
    for product in sorted_data:
        category = product['category']
        if category not in category_tables:
            category_tables[category] = []
        category_tables[category].append(product)

    # Generate HTML code for each table
    tables = ''
    for category, products in category_tables.items():
        tables += f'<h2>{category}</h2><table><thead><tr><th>Name</th><th>Price</th></tr></thead><tbody>'
        for product in products:
            name = product['name']
            price = product['price']
            tables += f'<tr><td>{name}</td><td>{price}</td></tr>'
        tables += '</tbody></table>'

    return tables

# Define a function to load the JSON data and generate HTML tables
def load_data(filename):
    with open(filename) as f:
        data = json.load(f)
    tables = generate_tables(data)
    return tables

@app.route('/')
def index():
    # Load the JSON data and generate HTML tables
    tables = load_data('products.json')

    # Render the template with the generated HTML tables
    return render_template('index.html', tables=tables)
