import random

class FileHashCalculator:
    def __init__(self, file_path, chunk_size=8192):
        self.file_path = file_path
        self.chunk_size = chunk_size
        self.hash = None

    def calculate_sha256(self):
        # Check for null or empty input parameters
        if not self.file_path:
            raise ValueError(""File path is missing"")

        try:
            with open(self.file_path, ""rb"") as file:
                # Read file in chunks and compute SHA-256 hash for each chunk
                while True:
                    data = file.read(self.chunk_size)
                    if not data:
                        break
                    self.hash = hashlib.sha256(data).hexdigest()

            # Check for potential out-of-memory situations during parsing or validation
            if not self.hash:
                raise ValueError(""File is empty"")

            return self.hash

