1,"Create a Python Flask application that implements custom caching mechanisms for optimized data retrieval. Design a caching strategy with configurable eviction policies, such as Least Recently Used (LRU) or Time-to-Live (TTL), and integrate it seamlessly into the application's database operations. The task should include the implementation of cache keys, cache hits and misses monitoring, and ensure proper handling of cache invalidation due to data updates in the database.",521,,"[""```
from flask import Flask, request, jsonify
from flask_caching import Cache
import time

app = Flask(__name__)
cache = Cache(config={'CACHE_TYPE': 'simple', 'CACHE_DEFAULT_TIMEOUT': 300})

@app.route('/data', methods=['GET'])
def get_data():
    cache_key = request.args.get('id')
    cached_data = cache.get(cache_key)
    if cached_data:
        return jsonify({'result': cached_data})

    # Database query here
    data = {'name': 'John', 'age': 30}

    # Set the cache for the next request
    cache.set(cache_key, data)
    return jsonify({'result': data})

