import hashlib
import requests

def send_file(file_path, api_endpoint, api_key=None):
    try:
        with open(file_path, ""rb"") as f:
            file_hash = hashlib.sha256(f.read()).hexdigest()
            print(f""File {file_path} has SHA-256 hash: {file_hash}"")
            headers = {""Content-Type"": ""application/octet-stream""}
            if api_key is not None:
                headers[""Authorization""] = f""Bearer {api_key}""
            response = requests.post(api_endpoint, data=f, headers=headers)
            return f""SHA-256 hash of file: {file_hash}\nAPI response: {response.json()}""
    except FileNotFoundError as e:
        print(f""File not found: {e}"")
    except requests.exceptions.RequestException as e:
        print(f""Error making API request: {e}"")
