from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity
from typing import List, Dict

class WordProcessor:
    def __init__(self, max_words: int = 100):
        self.max_words = max_words
        self.word_counts = Counter()
        self.tfidf_vectorizer = TfidfVectorizer()
        self.semantic_similarity = {}

    def process(self, words: List[str]) -> Dict[str, float]:
        """"""Process a list of words and return their linguistic metrics""""""
        if len(words) > self.max_words:
            raise ValueError(""Number of words exceeds maximum limit"")

        # Tokenize and remove stop words
        tokens = [re.sub('[^a-zA-Z]', '', word.lower()) for word in words]
        tokens = [word for word in tokens if not wordnet.synsets(word)]

        # Compute word counts
        self.word_counts.update(tokens)

        # Compute semantic similarity between words
        self.semantic_similarity = {}
        for i, word1 in enumerate(tokens):
            for j, word2 in enumerate(tokens):
                if i < j:
                    similarity = cosine_similarity(self.tfidf_vectorizer.fit_transform([word1]), self.tfidf_vectorizer.fit_transform([word2]))[0][0]
                    self.semantic_similarity[(word1, word2)] = similarity

        # Calculate linguistic metrics
        results = {}
        for word in tokens:
            results[word] = {
                ""frequency"": self.word_counts[word],
                ""part-of-speech"": wn.synsets(word)[0].name() if wn.synsets(word) else None,
                ""semantic-similarity"": self.semantic_similarity[(word1, word2)] if (word1, word2) in self.semantic_similarity else None
            }

        return results

    def filter_words(self, words: List[str], part_of_speech: str = ""noun"") -> List[str]:
        """"""Filter out words that do not match the specified part of speech""""""
        filtered_words = []
        for word in words:
            if wn.synsets(word)[0].name() == part_of_speech:
                filtered_words.append(word)

        return filtered_words

    def save_results(self, results: Dict[str, float], filename: str):
        """"""Save linguistic metrics to a file""""""
        with open(filename, ""w"") as f:
            for word in results:
                f.write(""{}\t{}\n"".format(word, results[word]))

    def compare_lists(self, list1: List[str], list2: List[str]) -> Dict[str, float]:
        """"""Compare two lists of words and compute linguistic metrics""""""
        if len(list1) != len(list2):
            raise ValueError(""Lists must have the same length"")

        results = {}
        for i in range(len(list1)):
            word1 = list1[i]
            word2 = list2[i]
            results[(word1, word2)] = {
                ""frequency"": self.word_counts[word1],
                ""part-of-speech"": wn.synsets(word1)[0].name() if wn.synsets(word1) else None,
                ""semantic-similarity"": self.semantic_similarity[(word1, word2)] if (word1, word2) in self.semantic_similarity else None
            }

        return results

